    def load_mapping_files(cls, data: Any) -> Any:
        """Load mapping options from inline JSON or UTF-8 JSON files."""
        if not isinstance(data, dict):
            return data

        import json
        from pathlib import Path

        data = data.copy()
        for field_name, option_name in (
            ("base_class_map", "--base-class-map"),
            ("enum_field_as_literal_map", "--enum-field-as-literal-map"),
        ):
            value = data.get(field_name)
            if not isinstance(value, str):
                continue

            stripped = value.lstrip()
            is_inline = stripped.startswith(("{", "[", '"', "-", *"0123456789")) or stripped in {
                "null",
                "true",
                "false",
            }
            try:
                if is_inline:
                    mapping = json.loads(value)
                else:
                    mapping = json.loads(Path(value).read_text(encoding="utf-8"))
            except UnicodeDecodeError as exc:
                raise ValueError(f"{option_name}: mapping file is not valid UTF-8: {value}") from exc
            except OSError as exc:
                raise ValueError(f"{option_name}: unable to read mapping file {value}: {exc}") from exc
            except json.JSONDecodeError as exc:
                source = "inline mapping" if is_inline else f"mapping file {value}"
                raise ValueError(f"{option_name}: invalid JSON in {source}: {exc}") from exc

            if not isinstance(mapping, dict):
                raise ValueError(f"{option_name}: JSON value must be an object")
            data[field_name] = mapping

        return data

